import{z as l,x as o,o as n,c as d,q as r,j as i,D as e,d as a,s as t,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"股利与回购","description":"","frontmatter":{"title":"股利与回购","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cf-dividends-buybacks.md","filePath":"econ/cf-dividends-buybacks.md","lastUpdated":1791063341000}'),c={name:"econ/cf-dividends-buybacks.md"};function F(p,E,D,h,f,C){const A=o("Mermaid");return n(),d("div",null,[E[2]||(E[2]=r('<h1 id="股利与回购" tabindex="-1">股利与回购 <a class="header-anchor" href="#股利与回购" aria-label="Permalink to &quot;股利与回购&quot;">​</a></h1><div class="epigraph"><p>股利的粘性是承诺的影子，回购的灵活是没有承诺的代价；拿灵活的工具去做承诺的事，公司下一次过冬就没了信用。</p><footer>—— 据 Lintner 1956 与 Baker–Wurgler 2002 整理</footer></div><p><a href="/econ/cf-financing-constraints">上一课</a>把融资约束的度量钉住：约束是 MM 无关性失效后的残差，度量要把需求与供给两只手分开。约束的另一面是冗余——企业手里的钱超过好项目的需要时，问题从「怎么拿钱」变成「怎么还钱」。主干课已在<a href="/econ/dividend-signaling">股利信号</a>、<a href="/econ/dividend-fcf">股利与自由现金流</a>与<a href="/econ/share-repurchase">股票回购</a>分别钉了三种解释，本课把两条支付管道放回同一张决策图：股利与回购各承接什么、为什么一个粘一个灵活、以及分配政策如何暴露上一课说的约束状态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Miller–Modigliani 1961 在无税无摩擦的世界里证明股利无关。现实的两个事实要一起解释：其一，股利极度粘性，削减罕见且常被市场重罚；其二，总量的支付方式持续从股利移向回购。粘性与灵活看似矛盾，其实是对同两组摩擦——承诺需求与信息不对称——的两种响应：前者买承诺，后者保留放弃承诺的自由。分错了对象，两条管道都会失效。</p><h3 id="分工的判据" tabindex="-1">分工的判据 <a class="header-anchor" href="#分工的判据" aria-label="Permalink to &quot;分工的判据&quot;">​</a></h3><p>判据是现金增多的<strong>持久性</strong>。持久盈利上台阶，用股利：Lintner 1956 的访谈模型里，公司盯住目标派息率做部分调整，\\(\\Delta D_t = a + s\\,(r E_t - D_{t-1}) + \\varepsilon_t\\)，每年只补齐目标缺口的一小部分——慢不是执行差，是故意买来的信誉资产。临时性现金，用回购：不抬高永续义务，情况变坏可以停。信息不对称越大，越该用回购，否则一项临时盈余会被市场读成永久承诺，日后削减变成信号灾难。</p><p><span class="marginnote">代入数字看「慢」：设目标股利比现在高 30 元、Lintner 系数取三分之一，今年只加 10 元，明年补剩余 20 元缺口的三分之一（约 6.7 元），再往后逐年递减、几何式收敛。表面像公司抠门，实际是在证明：敢加的那部分永远付得起。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>再叠两层解释。代理层：Jensen 1986 的自由现金流论证——分钱本身就是治理工具，现金留在不受约束的经理手里会被投进负 NPV 项目；<a href="/econ/agency-free-cash-flow">自由现金流代理成本</a>钉的正是这一条。市场层：Baker–Wurgler 2002 的迎合（catering）——股利溢价为正时公司开始派息，为负时停发，供给响应需求，说明派息决策不完全来自公司内部。两层解释共用一个可检验含义：股利的启动与停发，应在估值与投资者构成的变化处扎堆。</p>',10)),(n(),i(s,null,{default:e(()=>[t(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXCESS%5B%22%E7%8E%B0%E9%87%91%E8%B6%85%E8%BF%87%E5%A5%BD%E9%A1%B9%E7%9B%AE%E9%9C%80%E8%A6%81%22%5D%20--%3E%20Q1%7B%22%E7%8E%B0%E9%87%91%E5%A2%9E%E5%A4%9A%E6%98%AF%E6%8C%81%E4%B9%85%E7%9A%84%3F%22%7D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20DIV%5B%22%E8%82%A1%E5%88%A9%EF%BC%9A%E6%85%A2%E8%B0%83%E6%95%B4%E4%B9%B0%E6%89%BF%E8%AF%BA%22%5D%0A%20%20Q1%20--%3E%7C%E5%90%A6%7C%20Q2%7B%22%E4%BF%A1%E6%81%AF%E4%B8%8D%E5%AF%B9%E7%A7%B0%E5%A4%A7%3F%22%7D%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20BUY%5B%22%E5%9B%9E%E8%B4%AD%EF%BC%9A%E7%81%B5%E6%B4%BB%EF%BC%8C%E9%81%BF%E6%B0%B8%E4%B9%85%E6%89%BF%E8%AF%BA%22%5D%0A%20%20Q2%20--%3E%7C%E5%90%A6%7C%20MIX%5B%22%E5%9F%BA%E7%A1%80%E8%82%A1%E5%88%A9%E5%8A%A0%E7%89%B9%E5%88%AB%E5%9B%9E%E8%B4%AD%22%5D%0A%20%20DIV%20--%3E%20SIG%5B%22%E5%B8%82%E5%9C%BA%E8%AF%BB%E4%BD%9C%E6%8C%81%E4%B9%85%E7%9B%88%E5%88%A9%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20BUY%20--%3E%20AG%5B%22%E5%85%BC%E4%BD%9C%E8%87%AA%E7%94%B1%E7%8E%B0%E9%87%91%E6%B5%81%E6%B2%BB%E7%90%86%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("为什么粘性是理性的：股利一旦成为信号载体，削减就是自证坏消息，所以启动要慢、目标要稳——Lintner 的调整系数小到每年只补约三分之一缺口。为什么回购的时机常与直觉相反：公司往往在估值高时回购更多（迎合与便利窗口），回购公告的异常收益也小于股利首次公告——市场知道回购随时可撤。为什么分配政策能暴露约束状态：接上一课，受约束的公司囤现金（"),B("a",{href:"/econ/cash-holdings"},"现金持有"),a("的动机之一），根本谈不到分配；开始分配本身就是「内部资金已越过投资需求」的显示。总量的迁移（Fama–French 2001 的股利消失与回购崛起）因而同时是税制、期权激励与迎合三股力的合成。")],-1)),(n(),i(s,null,{default:e(()=>[t(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E7%9B%88%E5%88%A9%E6%8C%81%E4%B9%85%E4%B8%8A%E5%8F%B0%E9%98%B6%22%5D%20--%3E%20P%5B%22%E5%85%AC%E5%8F%B8%E5%8F%AA%E5%B0%8F%E5%B9%85%E6%8F%90%E9%AB%98%E8%82%A1%E5%88%A9%22%5D%0A%20%20P%20--%3E%20C%5B%22%E5%B8%82%E5%9C%BA%E6%8A%8A%E9%AB%98%E8%82%A1%E5%88%A9%E8%AF%BB%E4%BD%9C%E6%8C%81%E4%B9%85%E6%89%BF%E8%AF%BA%22%5D%0A%20%20C%20--%3E%20L%5B%22%E6%9C%AA%E6%9D%A5%E5%89%8A%E5%87%8F%20%3D%20%E8%87%AA%E8%AF%81%E5%9D%8F%E6%B6%88%E6%81%AF%22%5D%0A%20%20L%20--%3E%20D%5B%22%E4%BA%8E%E6%98%AF%E5%90%AF%E5%8A%A8%E6%85%A2%E3%80%81%E7%9B%AE%E6%A0%87%E7%A8%B3%EF%BC%9A%E7%B2%98%E6%80%A7%E8%A2%AB%E9%94%81%E6%AD%BB%22%5D%0A%20%20B%5B%22%E4%B8%B4%E6%97%B6%E7%8E%B0%E9%87%91%E8%B5%B0%E5%9B%9E%E8%B4%AD%E7%AE%A1%E9%81%93%22%5D%20--%3E%20F%5B%22%E9%9A%8F%E6%97%B6%E5%8F%AF%E5%81%9C%EF%BC%8C%E4%B8%8D%E8%BF%9B%E6%89%BF%E8%AF%BA%E5%AD%98%E9%87%8F%22%5D%0A%20%20F%20--%3E%20S%5B%22%E5%81%9C%E6%AD%A2%E5%9B%9E%E8%B4%AD%E4%B8%8D%E8%A7%A6%E5%8F%91%E4%BF%A1%E5%8F%B7%E7%81%BE%E9%9A%BE%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">直觉类比：股利像每月按时交给家里的生活费，交过几次后再突然停掉，全家都会往坏处想；回购像过年随手的红包，发了大家高兴，不发也没人多想。公司把「能持续的事」放进生活费，把「看情况的事」留给红包——两条管道各守各的信用，混用则会两头落空。</span></p><p><span class="marginnote">Lintner 1956 访谈 28 家美国公司的经理得出部分调整规则，调整速度系数大约在每年补齐目标缺口的四分之一到三分之一之间——粘性来自管理层自己承认的「不想回头的承诺」，不是数据噪声。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>税制改变均衡：投资者层面的税负差异决定股利折价还是溢价，各国不同，结论不可跨境直搬。不要把回购一律读成每股收益操纵：多数回购由现金冗余与股价判断驱动，操纵只是边际。迎合证据说明供给响应需求，不说明股利政策「由市场决定」——Lintner 的内部规则仍在。本课不展开回购与投资的挤出证据，那要接投资约束的识别设计。</p><p><span class="marginnote">常见误区：把回购一律当成「操纵每股收益」。注销式回购确实会机械抬高 EPS，但多数回购由现金冗余与估值判断驱动；市场也不是照单全收——回购公告的异常收益明显小于股利首次公告，因为人人都知道回购随时可以停，而股利不能。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>股利与回购的分工按现金持久性划界：持久的用股利买承诺，临时的用回购保灵活。</li><li>粘性是故意买来的信誉资产；Lintner 部分调整是它的机制化。</li><li>Jensen 1986 把分配读成治理工具；Baker–Wurgler 2002 把供给读成对溢价的迎合。</li><li>分配政策的启动本身就是约束状态的显示，接上一课的度量框架。</li><li>出处：Miller–Modigliani 1961；Lintner 1956；Jensen 1986；Baker–Wurgler 2002；Fama–French 2001。</li></ul>',7))])}const _=l(c,[["render",F]]);export{u as __pageData,_ as default};
